```typescript
import { NextRequest, NextResponse } from "next/server";

export const runtime = "nodejs";

const MAX_BYTES = 10 * 1024 * 1024;
const UPSTREAM_TIMEOUT_MS = 60_000;

const ALLOWED_FIELDS = [
  "grossSales",
  "netSales",
  "cashSystem",
  "spanSystem",
  "deliveryAppsSystem",
  "reversedTransactions",
  "cashActualHanded",
] as const;

type ExtractableField = (typeof ALLOWED_FIELDS)[number];
type ExtractedFields = Partial<Record<ExtractableField, number>>;

function buildPrompt(): string {
  return [
    "أنت مساعد يحلّل صورة لتقرير Z (تقرير إقفال اليوم) باللغة العربية.",
    "استخرج القيم التالية من الصورة وأرجعها بصيغة JSON فقط دون أي شرح أو نص إضافي.",
    "إن لم تجد قيمة معيّنة، اجعلها null.",
    "احذف فواصل الآلاف واستخدم النقطة (.) كفاصل عشري.",
    "",
    "المفاتيح المطلوبة بالضبط:",
    "- grossSales: إجمالي المبيعات",
    "- netSales: صافي المبيعات",
    "- cashSystem: النقدية حسب النظام",
    "- spanSystem: سبان",
    "- deliveryAppsSystem: تطبيقات التوصيل",
    "- reversedTransactions: حركات مرتجعة",
    "- cashActualHanded: النقدية المسلّمة فعليًا",
    "",
    "أرجع JSON فقط بهذا الشكل:",
    '{"grossSales": 0.0, "netSales": 0.0, "cashSystem": 0.0, "spanSystem": 0.0, "deliveryAppsSystem": 0.0, "reversedTransactions": 0.0, "cashActualHanded": 0.0}',
  ].join("\n");
}

function stripCodeFence(raw: string): string {
  let s = raw.trim();
  if (s.startsWith("```")) {
    s = s.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "");
  }
  return s.trim();
}

function coerceFields(parsed: unknown): ExtractedFields {
  const out: ExtractedFields = {};
  if (!parsed || typeof parsed !== "object") return out;
  const obj = parsed as Record<string, unknown>;
  for (const key of ALLOWED_FIELDS) {
    const v = obj[key];
    if (v === null || v === undefined) continue;
    const n = Number(v);
    if (Number.isFinite(n)) out[key] = n;
  }
  return out;
}

export async function POST(req: NextRequest) {
  const apiKey = process.env.GLM_API_KEY;
  const baseUrl = process.env.GLM_BASE_URL;
  const visionModel = process.env.GLM_VISION_MODEL;

  if (!apiKey || !baseUrl || !visionModel) {
    return NextResponse.json(
      { error: "خدمة تحليل الصور غير مُهيّأة. تواصل مع الإدارة." },
      { status: 503 },
    );
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { error: "صيغة الطلب غير صحيحة." },
      { status: 400 },
    );
  }

  const { imageBase64 } = (body ?? {}) as { imageBase64?: unknown };
  if (typeof imageBase64 !== "string" || imageBase64.length === 0) {
    return NextResponse.json(
      { error: "لم يتم توفير صورة." },
      { status: 400 },
    );
  }

  let mime = "image/jpeg";
  let dataUrl: string;
  if (imageBase64.startsWith("data:")) {
    const m = imageBase64.match(/^data:([^;]+);base64,/);
    if (!m) {
      return NextResponse.json(
        { error: "صيغة الصورة غير صحيحة." },
        { status: 400 },
      );
    }
    mime = m[1];
    dataUrl = imageBase64;
  } else {
    dataUrl = `data:${mime};base64,${imageBase64}`;
  }

  if (!mime.startsWith("image/")) {
    return NextResponse.json(
      { error: "الملف المُرفق ليس صورة." },
      { status: 415 },
    );
  }

  const rawBase64 = dataUrl.split(",")[1] ?? "";
  let byteLength = rawBase64.length;
  try {
    byteLength = Buffer.from(rawBase64, "base64").byteLength;
  } catch {
    // ignore
  }
  if (byteLength > MAX_BYTES) {
    return NextResponse.json(
      { error: "حجم الصورة كبير جدًا (الحد الأقصى ١٠ ميجابايت)." },
      { status: 413 },
    );
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), UPSTREAM_TIMEOUT_MS);

  try {
    const upstream = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: visionModel,
        temperature: 0,
        max_tokens: 2048,
        thinking: { type: "disabled" },
        messages: [
          {
            role: "user",
            content: [
              { type: "text", text: buildPrompt() },
              { type: "image_url", image_url: { url: dataUrl } },
            ],
          },
        ],
      }),
      signal: controller.signal,
    });

    if (!upstream.ok) {
      const text = await upstream.text().catch(() => "");
      return NextResponse.json(
        {
          error: "تعذّر تحليل الصورة من مزوّد الخدمة.",
          upstreamStatus: upstream.status,
          upstreamPreview: text.slice(0, 300),
        },
        { status: 502 },
      );
    }

    const data = (await upstream.json()) as {
      choices?: Array<{
        message?: { content?: string };
        finish_reason?: string;
      }>;
    };

    const choice = data.choices?.[0];
    const content = choice?.message?.content ?? "";
    const finishReason = choice?.finish_reason ?? null;

    if (!content.trim()) {
      return NextResponse.json(
        {
          error: "لم يتم استخراج أي بيانات من الصورة.",
          finishReason,
        },
        { status: 502 },
      );
    }

    const cleaned = stripCodeFence(content);
    let parsed: unknown;
    try {
      parsed = JSON.parse(cleaned);
    } catch {
      return NextResponse.json(
        {
          error: "تعذّر تفسير نتيجة التحليل.",
          finishReason,
          rawPreview: cleaned.slice(0, 300),
        },
        { status: 502 },
      );
    }

    const fields = coerceFields(parsed);
    return NextResponse.json({ fields, finishReason, model: visionModel });
  } catch (err) {
    if ((err as Error)?.name === "AbortError") {
      return NextResponse.json(
        { error: "انتهت مهلة تحليل الصورة. حاول مجددًا." },
        { status: 504 },
      );
    }
    return NextResponse.json(
      { error: "حدث خطأ غير متوقّع أثناء التحليل." },
      { status: 500 },
    );
  } finally {
    clearTimeout(timer);
  }
}
```

