```typescript
import { getSupabase, isSupabaseConfigured } from "./supabase";
import { DailyClosing, FinancialFields } from "../types";

const QUEUE_KEY = "cashier_offline_closings_queue";
const Z_REPORT_BUCKET = "z-reports";
const PROOF_BUCKET = "payment-proofs";

export interface SaveClosingInput {
  branchId: string;
  businessDate: string;
  reviewedData: FinancialFields;
  manualActualCash?: number;
  zReportImageUrl?: string;
  paymentProofImageUrls?: string[];
  aiExtractedData?: Partial<FinancialFields>;
  aiConfidence?: Record<string, number>;
  manuallyModifiedFields?: (keyof FinancialFields)[];
}

export interface ClosingResult {
  closing: DailyClosing;
  source: "supabase" | "local-queued";
  warnings: string[];
}

function dataUrlToBytes(dataUrl: string): { bytes: Uint8Array; mime: string } | null {
  const m = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!m) return null;
  const mime = m[1];
  const base64 = m[2];
  try {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return { bytes, mime };
  } catch {
    return null;
  }
}

export async function checkDuplicateClosing(
  branchId: string,
  businessDate: string,
): Promise<boolean> {
  if (!isSupabaseConfigured) return false;
  try {
    const supabase = getSupabase();
    const { data } = await supabase
      .from("daily_closings")
      .select("id")
      .eq("branch_id", branchId)
      .eq("business_date", businessDate)
      .maybeSingle();
    return Boolean(data);
  } catch {
    return false;
  }
}

async function tryUploadImage(
  dataUrl: string,
  bucket: string,
  pathPrefix: string,
): Promise<{ url: string | null; warning: string | null }> {
  if (!isSupabaseConfigured) {
    return { url: null, warning: null };
  }
  try {
    const parsed = dataUrlToBytes(dataUrl);
    if (!parsed) return { url: null, warning: null };
    const ext = parsed.mime === "image/png" ? "png" : parsed.mime === "image/webp" ? "webp" : "jpg";
    const fileName = `${pathPrefix}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
    const supabase = getSupabase();
    const { data, error } = await supabase.storage
      .from(bucket)
      .upload(fileName, parsed.bytes, { contentType: parsed.mime, upsert: false });
    if (error || !data) {
      return { url: null, warning: "تعذّر رفع صورة إلى التخزين — ستُحفظ محليًا." };
    }
    const { data: pub } = supabase.storage.from(bucket).getPublicUrl(data.path);
    return { url: pub.publicUrl, warning: null };
  } catch {
    return { url: null, warning: "تعذّر رفع صورة إلى التخزين — ستُحفظ محليًا." };
  }
}

function genId(): string {
  return `close-${Date.now()}`;
}

function readQueue(): SaveClosingInput[] {
  try {
    const raw = localStorage.getItem(QUEUE_KEY);
    return raw ? (JSON.parse(raw) as SaveClosingInput[]) : [];
  } catch {
    return [];
  }
}

function writeQueue(items: SaveClosingInput[]) {
  try {
    localStorage.setItem(QUEUE_KEY, JSON.stringify(items));
  } catch {
    // ignore
  }
}

export async function saveClosing(input: SaveClosingInput): Promise<ClosingResult> {
  const id = genId();
  const warnings: string[] = [];
  const now = new Date().toISOString();

  const baseClosing: DailyClosing = {
    id,
    branchId: input.branchId,
    businessDate: input.businessDate,
    status: "pending",
    reviewedData: { ...input.reviewedData },
    manualActualCash: input.manualActualCash,
    aiExtractedData: input.aiExtractedData,
    aiConfidence: input.aiConfidence,
    manuallyModifiedFields: input.manuallyModifiedFields,
    createdAt: now,
    updatedAt: now,
  };

  // Offline path
  if (!isSupabaseConfigured || typeof navigator !== "undefined" && !navigator.onLine) {
    const queue = readQueue();
    queue.push({ ...input });
    writeQueue(queue);
    return {
      closing: {
        ...baseClosing,
        zReportImageUrl: input.zReportImageUrl,
        paymentProofImageUrls: input.paymentProofImageUrls,
      },
      source: "local-queued",
      warnings: ["تم الحفظ محليًا وسيُرفع لاحقًا."],
    };
  }

  // Online path
  let uploadedZ: string | null = null;
  let uploadedProofs: string[] = [];

  if (input.zReportImageUrl) {
    const r = await tryUploadImage(input.zReportImageUrl, Z_REPORT_BUCKET, input.branchId);
    uploadedZ = r.url;
    if (r.warning) warnings.push(r.warning);
  }

  if (input.paymentProofImageUrls && input.paymentProofImageUrls.length > 0) {
    for (const dataUrl of input.paymentProofImageUrls) {
      const r = await tryUploadImage(dataUrl, PROOF_BUCKET, input.branchId);
      if (r.url) uploadedProofs.push(r.url);
      if (r.warning) warnings.push(r.warning);
    }
  }

  const supabase = getSupabase();
  const insertRow = {
    id,
    branch_id: input.branchId,
    business_date: input.businessDate,
    status: "pending",
    reviewed_data: input.reviewedData,
    manual_actual_cash: input.manualActualCash ?? null,
    z_report_image_url: uploadedZ,
    payment_proof_image_urls: uploadedProofs.length > 0 ? uploadedProofs : null,
    ai_extracted_data: input.aiExtractedData ?? null,
    ai_confidence: input.aiConfidence ?? null,
    manually_modified_fields: input.manuallyModifiedFields ?? null,
  };

  const { error } = await supabase.from("daily_closings").insert(insertRow);
  if (error) {
    // Fall back to local queue
    const queue = readQueue();
    queue.push({ ...input });
    writeQueue(queue);
    return {
      closing: {
        ...baseClosing,
        zReportImageUrl: input.zReportImageUrl,
        paymentProofImageUrls: input.paymentProofImageUrls,
      },
      source: "local-queued",
      warnings: [...warnings, "فشل الحفظ في الخادم — تم الحفظ محليًا."],
    };
  }

  // Audit logs
  try {
    await supabase.from("daily_closing_audit_logs").insert([
      {
        closing_id: id,
        actor_role: "cashier",
        action: "cashier_confirmed",
      },
    ]);
    if (input.aiExtractedData && Object.keys(input.aiExtractedData).length > 0) {
      await supabase.from("daily_closing_audit_logs").insert([
        {
          closing_id: id,
          actor_role: "ai",
          action: "ai_extracted",
        },
      ]);
    }
  } catch {
    // audit failures non-fatal
  }

  return {
    closing: {
      ...baseClosing,
      zReportImageUrl: uploadedZ ?? undefined,
      paymentProofImageUrls: uploadedProofs.length > 0 ? uploadedProofs : undefined,
    },
    source: "supabase",
    warnings,
  };
}
